import{_ as t,o as r,c as p,ag as n}from"./chunks/framework.CukOUUOK.js";const b=JSON.parse('{"title":"《标签的背叛》02｜欧洲：资本主义为什么没有被消灭，却被重新塑形——一个标签没有改变，里面的权力关系却改变了","description":"如果说朝鲜的问题是： 社会主义这个标签和制度现实逐渐分离。 欧洲则提供了一个完全不同的案例： 资本主义这个标签没有消失，但资本主义内部的社会关系发生了巨大变化。 19世纪的资本主义和今天北欧、德国、法国的资本主义，不是同…","frontmatter":{"title":"《标签的背叛》02｜欧洲：资本主义为什么没有被消灭，却被重新塑形——一个标签没有改变，里面的权力关系却改变了","categories":"政治思想史","tags":["意识形态","劳动与经济","制度","历史"],"description":"如果说朝鲜的问题是： 社会主义这个标签和制度现实逐渐分离。 欧洲则提供了一个完全不同的案例： 资本主义这个标签没有消失，但资本主义内部的社会关系发生了巨大变化。 19世纪的资本主义和今天北欧、德国、法国的资本主义，不是同…","date":"2026-09-19T12:00:00.000Z","series":"标签的背叛","seriesOrder":2},"headers":[],"relativePath":"posts/2026-09-19-betrayal-of-labels-02.md","filePath":"posts/2026-09-19-betrayal-of-labels-02.md","lastUpdated":1789992797000}'),s={name:"posts/2026-09-19-betrayal-of-labels-02.md"};function e(a,o,l,g,i,c){return r(),p("div",null,[...o[0]||(o[0]=[n('<h1 id="《标签的背叛》02-欧洲-资本主义为什么没有被消灭-却被重新塑形——一个标签没有改变-里面的权力关系却改变了" tabindex="-1">《标签的背叛》02｜欧洲：资本主义为什么没有被消灭，却被重新塑形——一个标签没有改变，里面的权力关系却改变了 <a class="header-anchor" href="#《标签的背叛》02-欧洲-资本主义为什么没有被消灭-却被重新塑形——一个标签没有改变-里面的权力关系却改变了" aria-label="Permalink to &quot;《标签的背叛》02｜欧洲：资本主义为什么没有被消灭，却被重新塑形——一个标签没有改变，里面的权力关系却改变了&quot;">​</a></h1><p>如果说朝鲜的问题是：</p><blockquote><p><strong>社会主义这个标签和制度现实逐渐分离。</strong></p></blockquote><p>欧洲则提供了一个完全不同的案例：</p><blockquote><p><strong>资本主义这个标签没有消失，但资本主义内部的社会关系发生了巨大变化。</strong></p></blockquote><p>19世纪的资本主义和今天北欧、德国、法国的资本主义，不是同一种劳动制度。私人产权没有消失。市场没有消失。企业没有消失。利润没有消失。但资本支配劳动的方式被一层层制度重新塑造。这说明一个非常重要的事情：</p><blockquote><p><strong>标签可以不变，制度内容却可以变化。</strong></p></blockquote><p>而变化的关键，不是国家突然良心发现。而是社会产生了组织化的反制能力。</p><h3 id="一、最初的问题-谁决定一天工作多久" tabindex="-1">一、最初的问题：谁决定一天工作多久？ <a class="header-anchor" href="#一、最初的问题-谁决定一天工作多久" aria-label="Permalink to &quot;一、最初的问题：谁决定一天工作多久？&quot;">​</a></h3><p>工业革命首先改变的是时间。农业劳动受到天气、季节和自然节律影响。工厂则不同。机器可以持续运转。资本可以持续积累。于是工厂需要工人适应机器。</p><p>19世纪早期英国大量工人每天工作14–16小时，部分达18小时，每周7天无休。儿童劳动也十分普遍——1833年工厂视察员的报告显示，纺织厂中约半数工人是18岁以下。</p><p>这意味着：</p><blockquote><p><strong>劳动时间第一次被系统性地变成资本组织生产的工具。</strong></p></blockquote><p>而工人面对的问题非常简单：</p><blockquote><p><strong>我能不能拒绝？</strong></p></blockquote><p>如果不能，那么所谓“自由签约”就只能在形式上存在。因为：你当然可以拒绝72小时工作。</p><p>但如果拒绝的代价是失去收入，而整个劳动力市场都要求你接受，那么个人自由的实际含义就非常有限。</p><p>这恰恰是马克思主义劳动批判的重要问题：<strong>所谓自由，实质是工人被迫出卖劳动力的自由。</strong></p><h3 id="二、最初的反抗为什么不起作用" tabindex="-1">二、最初的反抗为什么不起作用？ <a class="header-anchor" href="#二、最初的反抗为什么不起作用" aria-label="Permalink to &quot;二、最初的反抗为什么不起作用？&quot;">​</a></h3><p>因为工人是分散的。一个工人罢工。老板可以换一个。一间工厂罢工。资本可以寻找新的劳动力。所以：个人的不满很难改变生产关系。</p><p>早期反抗是零星且被残酷镇压的。1811–1816年卢德运动以捣毁机器反抗，1812年英国议会通过《捣毁机器法》定为死罪，数十人被处决或流放。1817年罗伯特·欧文首次提出“8小时工作、8小时休闲、8小时休息”——当时完全是乌托邦，没有任何力量支持它。</p><p><strong>这个阶段不存在任何制度化的反制能力。</strong> 工人的处境取决于雇主的个人良心。</p><p>于是工人开始组织起来。工会。互助会。政治组织。工人报刊。罢工基金。这些东西真正改变了博弈结构。因为老板面对的第一次不再是：</p><blockquote><p>一个说“不”的人。</p></blockquote><p>而是：</p><blockquote><p><strong>一千个能够共同说“不”的人。</strong></p></blockquote><h3 id="三、第一步-工时成为公共政策问题" tabindex="-1">三、第一步：工时成为公共政策问题 <a class="header-anchor" href="#三、第一步-工时成为公共政策问题" aria-label="Permalink to &quot;三、第一步：工时成为公共政策问题&quot;">​</a></h3><p><strong>1833年英国《工厂法》</strong>：禁止9岁以下儿童在纺织厂工作；9–13岁每天不超过9小时、每周不超过48小时；13–18岁每天不超过12小时；设立工厂视察员。</p><p>它的意义不在解决了多少问题，而在于确立了一个原则：</p><blockquote><p><strong>工时不再由雇主单方面决定，它成为公共政策问题。</strong></p></blockquote><p>**1847年《十小时工作日法》**规定女工和13–18岁青少年每天不超过10小时。由于成年男工的工时难以与女工、童工分开管理，这部法律实际上推动整个工厂体系向十小时过渡。</p><p>但这里必须立刻加一句限定，否则会变成“立法即胜利”的错觉：</p><p>1833年法案只设了 <strong>4名</strong> 工厂视察员监督全英国的工厂。工会随时可能被宣布非法，改革派随时可能在选举中落败，工厂主可以让童工在法定工时外“自愿加班”。</p><blockquote><p><strong>法律写下来，和权利能兑现，是两件事。这一点在此后两百年反复出现。</strong></p></blockquote><p>这也是00篇五问的第四问：<strong>它怎么避免被收编？</strong> 条文存在，不等于权力存在。</p><h3 id="四、八小时工作制不是自然进步-而是组织化的产物" tabindex="-1">四、八小时工作制不是自然进步，而是组织化的产物 <a class="header-anchor" href="#四、八小时工作制不是自然进步-而是组织化的产物" aria-label="Permalink to &quot;四、八小时工作制不是自然进步，而是组织化的产物&quot;">​</a></h3><p>19世纪后半叶，八小时工作制逐渐成为国际工人运动的重要要求。时间线值得完整记住，因为每一步都有人付了代价：</p><ul><li><strong>1866年</strong> 第一国际日内瓦代表大会正式提出八小时工作制口号</li><li><strong>1886年5月1日</strong> 全美约35万工人在2万多家企业罢工，芝加哥4万人参与</li><li><strong>5月3日</strong> 警察向罢工工人开枪打死两人</li><li><strong>5月4日</strong> 干草市场广场集会中炸弹爆炸，7名警察和至少4名工人死亡</li><li><strong>事后</strong> 8名领袖被捕，4人绞刑，1人狱中自杀</li><li><strong>1889年</strong> 第二国际将5月1日定为国际劳动节；同年伦敦煤气工人罢工拿下英国首个行业八小时工作制</li><li><strong>1918年</strong> 德国在百万工人大罢工和十一月革命中立法确立全国八小时工作制</li><li><strong>1919年</strong> 法国通过劳工法案明确每日8小时、每周48小时；<strong>国际劳工组织（ILO）第一号公约</strong>将八小时定为全球标准</li></ul><p>到1922年，48小时工作周成为多数欧洲工业工人的常态。</p><p><strong>从14–16小时到8小时，走了将近一百年。</strong></p><p>这里最重要的不是“八小时”三个字。而是：</p><blockquote><p><strong>劳动时间从老板的单方面决定，变成了社会谈判对象。</strong></p></blockquote><p>这就是反制能力制度化的第一个阶段。</p><h3 id="五、国家为什么会介入-俾斯麦这个反直觉的节点" tabindex="-1">五、国家为什么会介入？俾斯麦这个反直觉的节点 <a class="header-anchor" href="#五、国家为什么会介入-俾斯麦这个反直觉的节点" aria-label="Permalink to &quot;五、国家为什么会介入？俾斯麦这个反直觉的节点&quot;">​</a></h3><p>很多人喜欢把福利国家写成：</p><blockquote><p>工人斗争 → 国家妥协。</p></blockquote><p>这仍然太简单。</p><p><strong>现代社会保障制度的起源不是工人的胜利，而是一个保守主义政治家的计算。</strong></p><p>1878年俾斯麦颁布《反社会党人法》取缔社会民主党，同时推动社会保障立法。他自己的话说明了动机：</p><blockquote><p>“我的想法是赢得工人阶级，或者可以说，引诱工人阶级把国家看作一个社会机构，这个机构关心他们的福利，在他们年老时照顾他们。”</p></blockquote><p>三部法律：</p><p>年份法律出资结构1883《疾病保险法》覆盖约300万工人，雇主1/3、工人2/31884《工伤事故保险法》雇主全额承担1889《伤残和养老保险法》年满70岁可领养老金，雇主工人各半，国家补贴制度设计有三个关键：<strong>强制性</strong>（不是自愿参加）、<strong>三方共担</strong>（任何一方无法单独退出）、<strong>权利与义务挂钩</strong>（缴费才享受，不是施舍）。</p><p>1883至1913年，德国参保工人从300万增至1450万。20世纪初，英法等30余国效仿。</p><h3 id="这一节有两层意义-第二层更重要" tabindex="-1">这一节有两层意义，第二层更重要 <a class="header-anchor" href="#这一节有两层意义-第二层更重要" aria-label="Permalink to &quot;这一节有两层意义，第二层更重要&quot;">​</a></h3><p><strong>第一层</strong>：推动者的主观动机和制度的客观效果可以完全不同。俾斯麦想瓦解工人运动，客观上建立了世界上第一个完整的社会保障法律体系。</p><p><strong>第二层</strong>：如果欧洲劳动者权益的进化是“自下而上争来的”，俾斯麦就是反例——他是自上而下的国家吸纳，而且明确以压制工人阶级政治组织为目的。</p><p><strong>但必须补一句，否则俾斯麦会被误读成“统治者的良心”。</strong></p><p>俾斯麦之所以算这笔账，是因为压力已经大到不算不行——社民党在选举中崛起，工人组织在壮大。他面对的不是“要不要让步”，而是“不让步的代价更高”。</p><blockquote><p><strong>同样是自上而下的吸纳，有没有压力从下面顶着，性质完全不同。</strong><br><strong>有压力顶着，它是回应与收编的混合；没有压力顶着，它就只剩收编。</strong></p></blockquote><p>这一点是本篇与朝鲜篇的接合处——那里，自上而下的动作从不需要向任何人解释。</p><h3 id="六、三股力量模型" tabindex="-1">六、三股力量模型 <a class="header-anchor" href="#六、三股力量模型" aria-label="Permalink to &quot;六、三股力量模型&quot;">​</a></h3><p>如果把欧洲劳动制度的形成过程压缩，可以看到三股力量：</p><p>力量机制局限自下而上的社会压力罢工、示威、舆论曝光制造政治成本需要付出代价；可能被镇压；能量难以沉淀横向的组织化谈判工会与雇主协会的集体协议直接设定规则依赖工会密度；可被法律削弱；会自然衰退自上而下的国家制度化劳动法、社会保险、福利国家具有双重性：既回应压力，也收编压力这三者不是互相替代。它们是互相塑造。社会压力让谈判拥有筹码。谈判结果变成制度模板。制度又反过来保护组织。于是形成循环：</p><blockquote><p><strong>社会组织 → 压力 → 国家回应 → 制度化 → 保护组织 → 下一轮谈判。</strong></p></blockquote><p><strong>反过来也成立</strong>：当工会密度下降（横向力量衰退），街头压力随之减弱，立法就失去了推动者——这正是1980年代之后发生的事。</p><h3 id="七、黄金时代与它的五个偶然条件" tabindex="-1">七、黄金时代与它的五个偶然条件 <a class="header-anchor" href="#七、黄金时代与它的五个偶然条件" aria-label="Permalink to &quot;七、黄金时代与它的五个偶然条件&quot;">​</a></h3><p><strong>1942年贝弗里奇报告</strong>提出消灭“五大恶”，主张社会保障应当是普遍的、统一的、综合的。</p><ul><li><strong>英国1948年</strong>通过《国民保险法》《国民健康服务法》，建立NHS，宣布成为第一个“福利国家”</li><li><strong>瑞典</strong>战后建立覆盖养老、医疗、住房、教育、育儿的全方位体系</li><li><strong>德国</strong>1957年建立动态养老金、1969年失业保险、1983年长期护理保险，确立“社会市场经济”</li><li><strong>法国</strong>1946年宪法序言写入健康权、休息权、工会权、罢工权</li></ul><p>工时持续缩短：</p><ul><li><strong>德国</strong>金属行业从战后48小时经多轮集体谈判降至40小时；1984年IG Metall发起35小时斗争、七周罢工，1995年在“全额工资补偿”条件下实现</li><li><strong>法国</strong>1936年《马提尼翁协议》降至40小时并首次建立带薪休假；1982年降至39小时；2000年《奥布里法》降至35小时</li><li><strong>瑞典</strong>从1920年的55小时经数十年降至1973年的40小时</li></ul><p>驱动力是五重的：工人阶级政党执政、<strong>冷战制度竞争</strong>、凯恩斯主义、战后经济高速增长、工会力量的巅峰（西欧工会密度普遍30%–80%）。</p><p><strong>这五重条件是一个偶然的叠加。</strong> 其中任何一个缺失，结果都会不同。</p><h3 id="关于-冷战制度竞争-这一条" tabindex="-1">关于“冷战制度竞争”这一条 <a class="header-anchor" href="#关于-冷战制度竞争-这一条" aria-label="Permalink to &quot;关于“冷战制度竞争”这一条&quot;">​</a></h3><p>这一条常被一笔带过，但它揭示了一件反直觉的事：</p><blockquote><p><strong>欧洲工人的福利，部分地是资本主义“被威胁”的产物。</strong></p></blockquote><p>福利国家的黄金时代，与苏联阵营的存在在时间上高度重合。这不是巧合——当世界上还摆着另一个宣称“我们能养活工人”的制度时，资本主义必须证明自己也能，而且要证明得更好。</p><p>这是一种<strong>来自体系之外的、不以工人意志为转移的外部压力</strong>。它使得“让步”在相当长一段时间里成为统治精英的理性选择，而不是被迫的施舍。</p><p><strong>这就引出一个必须诚实提出的问题：1991年之后，这个压力源消失了。</strong> 而西欧工会密度的下跌，恰好是从1970年代峰值开始的——两条曲线的时间关系值得追问，但本篇不敢断言因果。</p><p>能确定的只是：</p><blockquote><p><strong>反制能力不仅需要内部的组织者，有时还需要一个外部替代方案的存在来维持精英让步的动机。当这个替代方案消失，维持的成本就全部落回劳动者自己身上——而他们正在变少。</strong></p></blockquote><h3 id="八、欧洲不是一块铁板" tabindex="-1">八、欧洲不是一块铁板 <a class="header-anchor" href="#八、欧洲不是一块铁板" aria-label="Permalink to &quot;八、欧洲不是一块铁板&quot;">​</a></h3><p>前面的叙述容易给人一种“欧洲”是单一案例的错觉。它不是。</p><p><strong>欧洲提供的是一组不同制度组合如何限制资本权力的比较实验。</strong></p><h3 id="_8-1-北欧-马克思没有预见的回答" tabindex="-1">8.1 北欧：马克思没有预见的回答 <a class="header-anchor" href="#_8-1-北欧-马克思没有预见的回答" aria-label="Permalink to &quot;8.1 北欧：马克思没有预见的回答&quot;">​</a></h3><p>北欧各国社会民主党——瑞典社会民主工人党（1889）、挪威工党（1887）、丹麦社会民主党（1871）——成立之初的理论纲领都带有马克思恩格斯思想的深刻痕迹。挪威工党早期甚至加入了共产国际。</p><p><strong>北欧的高福利，从思想源头上说是马克思主义影响下工人运动的产物。</strong></p><p>但北欧工人运动做了一个马克思本人未必赞同的选择：<strong>放弃暴力革命，走议会民主和渐进改良。</strong></p><p>这个转折有血的代价。1918年芬兰内战约3.7万人死亡；1931年瑞典“奥达伦事件”，军队向罢工工人开枪，5人死亡。</p><p>1930年代大萧条期间，瑞典社民党与农民联盟达成“奶牛交易”：城市工人支持农产品价格保护，换取农民对全面福利体系的支持。<strong>从追求“废除资本主义”转向“驯服资本主义”。</strong></p><p>1938年瑞典《萨尔茨耶巴登协议》：工会克制激进罢工，雇主承认工会合法地位——阶级冲突从街头转入会议室。</p><p><strong>三大支柱</strong>：</p><ul><li><strong>集体谈判取代法定最低工资</strong>（丹麦瑞典覆盖率约84%–89%，芬兰冰岛约90%，挪威约67%）</li><li><strong>普惠福利取代选择性救济</strong>（福利是公民权利而非施舍）</li><li><strong>高税收支撑再分配</strong>（瑞典个税最高边际税率57%，税收占GDP约51%）</li></ul><p><strong>关键在工会性质</strong>：北欧工会是独立于政府和雇主的自治组织，经费来自会员会费而非企业拨付，领导人由工人选举而非上级任命，有权组织罢工、签订覆盖全行业的协议，且不需要政府批准。</p><p>2026年8月挪威空管员罢工是个好例子。他们年薪约合120万人民币、每周37小时，诉求不是涨薪而是改善排班——因为结构性人员短缺导致超负荷。民众反应是冷静旁观。</p><p><strong>差距不在收入，在权利：一个年薪百万的劳动者有制度化的渠道去争“不被过度消耗”。</strong></p><p>注意这里争的是什么：<strong>不是分配（分多少），而是劳动过程本身怎么组织（排班）。</strong> 反制能力的指向不只是钱，还包括“我怎么被使用”——这才是最难被收买、也最难被替代的部分。</p><p><strong>北欧不是“天生好命”。</strong> 19世纪末的北欧同样贫富悬殊、工人赤贫，瑞典有数十万人因饥饿移民美国。高福利是工人用一百年组织、斗争、谈判换来的——工会密度不是自然形成的，是一代代人加入工会、缴纳会费、参与罢工、承受报复积累起来的。</p><h3 id="_8-2-莱茵模式-共决制把问题推进到企业内部" tabindex="-1">8.2 莱茵模式：共决制把问题推进到企业内部 <a class="header-anchor" href="#_8-2-莱茵模式-共决制把问题推进到企业内部" aria-label="Permalink to &quot;8.2 莱茵模式：共决制把问题推进到企业内部&quot;">​</a></h3><p>德国、法国、奥地利、荷兰：以社会保险为核心，雇主工人共同缴费，强调“社会伙伴关系”。</p><p>最独特的是德国<strong>劳资共决制</strong>：500人以上企业监事会必须有工人代表，2000人以上工人代表占一半席位且监事会主席在僵局时有决定权；煤钢行业工人代表直接进入管理层任“劳工董事”。</p><p>这并不满足于：</p><blockquote><p>工人可以要求更多工资。</p></blockquote><p>而开始问：</p><blockquote><p><strong>工人能不能参与企业重大决策？</strong></p></blockquote><p><strong>在德国，企业不只属于股东，也属于工人和社区。</strong></p><p>另一根支柱是<strong>双元制职业教育</strong>：每周3–4天企业实践、1–2天学校理论，培养出的是问题解决者和质量守护者，不只是操作者。</p><h3 id="_8-3-盎格鲁-撒克逊与南欧" tabindex="-1">8.3 盎格鲁-撒克逊与南欧 <a class="header-anchor" href="#_8-3-盎格鲁-撒克逊与南欧" aria-label="Permalink to &quot;8.3 盎格鲁-撒克逊与南欧&quot;">​</a></h3><p>英国、爱尔兰：福利水平较低，劳动市场更灵活，工会力量较弱。英国允许劳动者“自愿书面放弃”每周48小时上限——这在北欧和莱茵模式国家不可想象。</p><p>意大利、西班牙、希腊、葡萄牙：覆盖面不均，正规部门保障较好、非正规部门薄弱；青年失业率长期高企；劳动力市场存在正式工与临时工的严重“双轨制”。</p><p><strong>同为资本主义，北欧和南欧工人的处境相差甚远。这再次说明：决定处境的不是标签，是反制能力的组织形态。</strong></p><h3 id="九、正在失去什么-衰退的机制" tabindex="-1">九、正在失去什么：衰退的机制 <a class="header-anchor" href="#九、正在失去什么-衰退的机制" aria-label="Permalink to &quot;九、正在失去什么：衰退的机制&quot;">​</a></h3><p>这是本篇最不能省略的一节，因为如果只讲到福利国家的成就，欧洲就会被写成终点。</p><p><strong>零工经济</strong>：Uber、Deliveroo等催生大量“独立承包商”，不享受最低工资、带薪休假、社会保险——这是对两百年成果的直接挑战。</p><p><strong>工会衰退</strong>：西欧工会密度从1970年代峰值持续下降。<strong>法国已降至约8%，英国约23%，德国约16%。</strong></p><p>这里需要一个机制解释，否则“衰退”只是被描述，没被理解。</p><p><strong>米歇尔斯（Robert Michels）在《政党社会学》中提出的“寡头统治铁律”恰好提供了它</strong>：</p><blockquote><p>任何大规模组织，无论纲领多么民主、多么平等主义，都必然产生专业化的领袖集团；领袖会逐渐脱离群众、追求自身存续，最终<strong>组织目标被置换为组织自身的存续</strong>。</p></blockquote><p>米歇尔斯本人是社会主义者，他的批判源于对社会主义政党的失望。这条铁律最锋利之处在于：</p><blockquote><p><strong>它不依赖任何恶意假设</strong>——不需要工会领袖变坏、不需要有人腐败，仅凭“组织”这一形式本身，异化就会发生。</p></blockquote><p>这解释了两件事：</p><ul><li><strong>工会为什么会衰退</strong>：不只是外部打压的结果，也来自内部的官僚化——当一个组织的主要精力转向维持自身（会费、机构、谈判席位），它与普通会员的联系就会松弛，会员就会用脚投票。</li><li><strong>反制能力天然具有熵增倾向</strong>：它不是被打败的，它是在正常运转中慢慢失去与“被代表者”的连接。</li></ul><blockquote><p><strong>这意味着反制能力需要一种对抗自身官僚化的机制——这正是00篇五问中“谁保证它持续”和“它怎么避免被收编”这两个问题真正的难度所在。</strong></p></blockquote><p><strong>全球化竞次</strong>：资本全球流动寻找低成本，单一国家的保障面临“race to the bottom”压力。</p><p><strong>约束自身的刚性代价</strong>：2026年大众集团深陷泥潭——共决制让裁员关厂难如登天，而电动车时代需要快速迭代、产线随时改、工厂说关就关。燃油车时代越值钱的东西（干了30年的老师傅、极致打磨的工艺、盘根错节的劳资合同），在电动车时代成了越沉重的包袱。</p><p><strong>老师傅闭着眼能装发动机，但电动车没有发动机。</strong></p><blockquote><p><strong>约束不是只有收益。</strong> 它本质上是把“灵活性”换成“稳定性”。在技术范式剧变的时代，这笔交易的代价会显现。</p></blockquote><h3 id="十、这说明-制度-不是仓库-而是能力" tabindex="-1">十、这说明“制度”不是仓库，而是能力 <a class="header-anchor" href="#十、这说明-制度-不是仓库-而是能力" aria-label="Permalink to &quot;十、这说明“制度”不是仓库，而是能力&quot;">​</a></h3><p>欧洲经常给人一种错觉：工会已经存在。福利制度已经存在。所以制度就会一直在那里。不是。</p><p><strong>制度的背后其实是一种能力。</strong></p><p>如果年轻人不再参加工会。如果劳动关系越来越碎片化。如果企业越来越容易跨国转移。如果工人越来越以个人身份面对平台。那么：旧的组织结构就可能失去实际力量。法律仍然存在。机构仍然存在。名称仍然存在。</p><p><strong>但实际的反制能力可能开始下降。</strong></p><p>这就是：</p><blockquote><p><strong>形式没有消失，内容却开始变化。</strong></p></blockquote><p>这其实也是“标签的背叛”在欧洲的另一种表现——它证明这种背叛<strong>不专属于社会主义国家</strong>。任何标签，只要它背后的能力停止更新，都会被慢慢掏空。</p><h3 id="十一、标签与内容的交叉-一个必须点破的讽刺" tabindex="-1">十一、标签与内容的交叉：一个必须点破的讽刺 <a class="header-anchor" href="#十一、标签与内容的交叉-一个必须点破的讽刺" aria-label="Permalink to &quot;十一、标签与内容的交叉：一个必须点破的讽刺&quot;">​</a></h3><p>这里出现了一个标签上的讽刺。许多20世纪欧洲国家保留了“资本主义”身份。但它们吸收了大量原本由社会主义、工人运动和社会民主主义提出的要求：工时限制、社会保险、工会权利、集体谈判、公共医疗、公共教育、劳资协商与劳动保护。</p><p>反过来，许多宣称社会主义的国家，却又在现实中形成了高度集中的国家行政体系，只是在产权主体上发生了变化。</p><p>于是：</p><blockquote><p><strong>标签和内容发生了交叉。</strong><br><strong>资本主义国家吸收了一些社会主义传统的制度要求。</strong><br><strong>社会主义国家又可能保留大量资本主义式的等级控制关系，只是产权主体发生了变化。</strong></p></blockquote><p>这就是为什么：</p><blockquote><p><strong>不能只看一个国家自称什么。</strong></p></blockquote><p>必须看：</p><p><strong>社会究竟获得了什么控制权。</strong></p><h3 id="十二、欧洲真正留下的答案-是-冲突必须有出口" tabindex="-1">十二、欧洲真正留下的答案，是“冲突必须有出口” <a class="header-anchor" href="#十二、欧洲真正留下的答案-是-冲突必须有出口" aria-label="Permalink to &quot;十二、欧洲真正留下的答案，是“冲突必须有出口”&quot;">​</a></h3><p>工人与资本之间不会没有矛盾。政府和社会之间也不会没有矛盾。企业内部也不会没有矛盾。真正重要的是：</p><blockquote><p><strong>矛盾有没有制度化出口。</strong></p></blockquote><p>劳动者可以组织。工会可以谈判。谈判失败可以罢工。罢工可能推动立法。立法可以保护下一轮谈判。这意味着：一个人的“不接受”，可以经过制度：变成集体行动。集体行动再变成：政治成本。政治成本再变成：制度调整。</p><p><strong>这就是压力传导。</strong></p><p>回到00篇的统一变量——<strong>欧洲演示的是通道敞开时会发生什么</strong>：不是资本变善良了，而是“不”有了出口，于是让步成了理性选择。</p><h3 id="结语-资本主义没有消失-资本的-任性-被限制了" tabindex="-1">结语：资本主义没有消失，资本的“任性”被限制了 <a class="header-anchor" href="#结语-资本主义没有消失-资本的-任性-被限制了" aria-label="Permalink to &quot;结语：资本主义没有消失，资本的“任性”被限制了&quot;">​</a></h3><p>因此，欧洲的故事不能写成：</p><blockquote><p>工人最终战胜资本。</p></blockquote><p>更不能写成：</p><blockquote><p>资本主义终于变好了。</p></blockquote><p>更准确的描述是：</p><blockquote><p><strong>资本、劳动和国家之间形成了一种持续变化的制度均衡。</strong></p></blockquote><p>资本保留。市场保留。利润保留。私人所有保留。但劳动者获得了组织能力。国家承担了制度化功能。企业接受了集体谈判。于是：</p><blockquote><p><strong>资本仍然很强，但不再是唯一强者。</strong></p></blockquote><p>这才是欧洲两百年真正值得研究的地方。它证明的不是某种制度是终点。而是：</p><blockquote><p><strong>一个社会可以通过组织，把原本只能个人承担的“不”，逐渐变成一种制度化的社会力量。</strong></p></blockquote><p>但同样，它也证明：</p><blockquote><p><strong>这种力量一旦停止组织、停止更新，就可能再次衰退。</strong></p></blockquote><h3 id="附-不是终点论" tabindex="-1">附：不是终点论 <a class="header-anchor" href="#附-不是终点论" aria-label="Permalink to &quot;附：不是终点论&quot;">​</a></h3><p>最后必须拆掉一个可能的误读：这不是“欧洲是终点、中国在追赶、朝鲜是反面”。</p><p>欧洲自己正在失去一部分好不容易建立起来的东西——工会密度在跌，零工经济在绕开两百年的制度成果，全球竞次在压，共决制在技术变革面前显出刚性。</p><p><strong>没有任何制度一劳永逸。</strong> 真正稀缺的不是某个完美的制度安排，而是<strong>一种允许制度被持续纠错的机制</strong>——一种让受损者能够持续地说“不”、并且这个“不”能产生成本的机制。</p><p>这种机制本身就是脆弱的，需要被不断维护。这就是欧洲两百年真正教给我们的东西。</p><blockquote><p><strong>下一篇</strong>：03｜中国：当“社会主义”成为一个仍在定义中的词<br> 前两篇分别演示了“通道关闭”与“通道敞开（又正在变窄）”。中国篇处理第三种情形：<strong>一条尚未定型的通道，以及一句把所有问题都收进去、也因此无法自我闭合的宪法条文。</strong></p></blockquote><hr><blockquote><p>本文同步自知乎，<a href="https://zhuanlan.zhihu.com/p/2084659436950504810" target="_blank" rel="noreferrer">查看原文</a></p></blockquote>',170)])])}const h=t(s,[["render",e]]);export{b as __pageData,h as default};
